-- Articles demandés par Tom le 10/11/2026 (FR + EN) : Manchester United relégable, avant-papier du 7e tour de Coupe de France, surprises du 5e tour de Gambardella.
INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured", "en_title", "en_dek", "en_body_html", "en_published")
SELECT 'Manchester United relégable : Carrick au bord du licenciement', 'manchester-united-relegable-carrick-au-bord-du-licenciement', 'Malgré un 4-4 fou contre Aston Villa, Manchester United passe la trêve à la 18e place de Premier League, avec une seule victoire en 10 matchs. Michael Carrick pourrait être licencié dans les prochains jours.', '<p>Manchester United passe la trêve internationale dans la zone rouge. Une phrase qu''on n''avait plus écrite depuis 40 ans. Et pour <strong>Michael Carrick</strong>, ces deux semaines sans match pourraient être les dernières sur le banc d''Old Trafford.</p><h2>Un 4-4 complètement fou</h2><p>Dimanche 8 novembre, pour la 10e journée de Premier League, United reçoit Aston Villa. Après moins de quatre minutes, c''est déjà 0-2 : un but d''Alysson dès la 1re minute, puis <strong>Nicolas Jackson</strong>. Jamais United n''avait été mené 2-0 aussi tôt dans un match de Premier League.</p><p>Bruno Fernandes (sur penalty) et Youri Tielemans remettent les deux équipes à égalité avant la pause. Mais au retour des vestiaires, rebelote : penalty de John McGinn, puis but de Leon Goretzka. 2-4 à la 53e minute.</p><p>Beaucoup de supporters quittent le stade. Ils ont eu tort. Entrés en jeu, <strong>Joshua Zirkzee</strong> (90+2) puis <strong>Patrick Dorgu</strong>, de la tête à la 96e minute, arrachent un 4-4 improbable.</p><h2>18e et une seule victoire</h2><p>Le point ne change rien au classement. Après 10 journées, Manchester United est 18e, relégable, avec une seule victoire en championnat, au mois d''août. La série sans victoire en Premier League monte à huit matchs, et la défense a déjà encaissé 30 buts toutes compétitions confondues.</p><p>Selon The Athletic, United est assuré de passer au moins 15 jours de suite dans la zone de relégation, du jamais-vu depuis 1986. Et l''ambiance est lourde : les supporters ont encore manifesté contre les propriétaires du club pendant le match.</p><h2>Carrick sur la sellette</h2><p>Après le match, Michael Carrick a refusé de parler de démission : « Nous sommes en novembre. Je n''aime pas la situation ni nos résultats, mais on peut clairement faire quelque chose. » Même Patrick Dorgu, le héros du jour, ne cachait pas sa frustration : « Je ne suis pas content. Chacun doit se demander s''il en fait assez. »</p><p>Mais selon The Athletic et The Guardian, cités par Ouest-France, la direction va réévaluer l''avenir de son entraîneur pendant la trêve, et un licenciement est désormais envisagé. Des noms circulent déjà, comme <strong>Eddie Howe</strong> ou <strong>Mauricio Pochettino</strong>. Rien n''est officiel pour le moment.</p><h2>Prochain match : Liverpool</h2><p>La reprise ne fera pas de cadeau. Le 22 novembre, United se déplace à Anfield pour affronter Liverpool, son grand rival. Avec ou sans Carrick, le club le plus titré d''Angleterre joue déjà sa saison. ⚽</p><h2>Sources</h2><p><a href="https://www.skysports.com/football/news/13593226/man-utd-4-4-aston-villa-patrick-dorgu-levels-in-the-96th-minute-as-united-come-from-two-down-twice-to-earn-incredible-draw" target="_blank" rel="noopener noreferrer">Sky Sports</a>, <a href="https://www.espn.com/soccer/story/_/id/50421297/man-united-aston-villa-premier-league" target="_blank" rel="noopener noreferrer">ESPN</a>, <a href="https://www.nytimes.com/athletic/live-blogs/manchester-united-vs-aston-villa-live-updates-premier-league-score-result/Efhp3vFlL6wC/" target="_blank" rel="noopener noreferrer">The Athletic</a>, <a href="https://www.ouest-france.fr/sport/football/angleterre/manchester-united/premier-league-manchester-united-desormais-relegable-michael-carrick-devrait-etre-licencie-pendant-la-treve-1edaf214-dcd0-11f1-a62b-776e3051b0df" target="_blank" rel="noopener noreferrer">Ouest-France</a>.</p><p>— Passe D</p>', 'article', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'actualites'),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  now(), now(), 3, false, 'Manchester United in the drop zone: Carrick on the brink', 'Despite a crazy 4-4 draw with Aston Villa, Manchester United go into the break 18th in the Premier League, with a single win in 10 games. Michael Carrick could be sacked in the coming days.', '<p>Manchester United will spend the international break in the relegation zone. A sentence nobody had written in 40 years. And for <strong>Michael Carrick</strong>, these two weeks without a game could be his last on the Old Trafford bench.</p><h2>A crazy 4-4</h2><p>On Sunday 8 November, in the 10th round of the Premier League, United hosted Aston Villa. Within four minutes it was 0-2: Alysson scored in the 1st minute, then <strong>Nicolas Jackson</strong>. United had never been 2-0 down so early in a Premier League game.</p><p>Bruno Fernandes (penalty) and Youri Tielemans levelled before the break. But after half-time, the same again: a John McGinn penalty, then a Leon Goretzka goal. 2-4 after 53 minutes.</p><p>Many fans left the stadium. They were wrong. Off the bench, <strong>Joshua Zirkzee</strong> (90+2) and then <strong>Patrick Dorgu</strong>, with a header in the 96th minute, snatched an unlikely 4-4.</p><h2>18th with a single win</h2><p>The point changes nothing in the table. After 10 rounds, Manchester United are 18th, in the drop zone, with just one league win, back in August. The league winless run is now eight games, and the defence has already conceded 30 goals in all competitions.</p><p>According to The Athletic, United are guaranteed to spend at least 15 days in a row in the relegation zone, something not seen since 1986. And the mood is heavy: fans protested once again against the club''s owners during the game.</p><h2>Carrick under pressure</h2><p>After the game, Michael Carrick refused to talk about resigning: "We''re in November. I don''t like the situation or the results, but we can definitely do something about it." Even Patrick Dorgu, the hero of the day, did not hide his frustration: "I don''t feel happy. Everyone needs to look into himself and ask himself if he is doing enough."</p><p>But according to The Athletic and The Guardian, the club will reassess its coach''s future during the break, and a sacking is now being considered. Names are already circulating, such as <strong>Eddie Howe</strong> and <strong>Mauricio Pochettino</strong>. Nothing is official yet.</p><h2>Next up: Liverpool</h2><p>The restart will be no gift. On 22 November, United travel to Anfield to face their great rivals Liverpool. With or without Carrick, England''s most successful club is already playing for its season. ⚽</p><h2>Sources</h2><p><a href="https://www.skysports.com/football/news/13593226/man-utd-4-4-aston-villa-patrick-dorgu-levels-in-the-96th-minute-as-united-come-from-two-down-twice-to-earn-incredible-draw" target="_blank" rel="noopener noreferrer">Sky Sports</a>, <a href="https://www.espn.com/soccer/story/_/id/50421297/man-united-aston-villa-premier-league" target="_blank" rel="noopener noreferrer">ESPN</a>, <a href="https://www.nytimes.com/athletic/live-blogs/manchester-united-vs-aston-villa-live-updates-premier-league-score-result/Efhp3vFlL6wC/" target="_blank" rel="noopener noreferrer">The Athletic</a>, <a href="https://www.ouest-france.fr/sport/football/angleterre/manchester-united/premier-league-manchester-united-desormais-relegable-michael-carrick-devrait-etre-licencie-pendant-la-treve-1edaf214-dcd0-11f1-a62b-776e3051b0df" target="_blank" rel="noopener noreferrer">Ouest-France</a>.</p><p>— Passe D</p>', true
ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured", "en_title", "en_dek", "en_body_html", "en_published")
SELECT 'Coupe de France : les Ligue 2 entrent en jeu, les petits poucets rêvent', 'coupe-de-france-7e-tour-les-ligue-2-entrent-en-jeu-les-petits-poucets-revent', 'Du 12 au 15 novembre, le 7e tour de la Coupe de France voit arriver les clubs de Ligue 2. Chambéry-Grenoble, Cambrai-Amiens, Choisy-au-Bac-Caen, le petit poucet Violaines… Passe D vous présente les affiches à ne pas rater.', '<p>C''est le moment que tous les petits clubs attendent. Du jeudi 12 au dimanche 15 novembre, le 7e tour de la Coupe de France marque l''entrée en lice des clubs de <strong>Ligue 2</strong>. Face à eux, des équipes de Régional, parfois de district, qui jouent le match de leur vie. Passe D vous présente les affiches à ne pas rater.</p><h2>Les chocs David contre Goliath</h2><ul><li><strong>Chambéry (R1) – Grenoble (L2)</strong>, jeudi 12 novembre à 19h. Le match d''ouverture, face à la lanterne rouge de Ligue 2. Le piège est tendu.</li><li><strong>Tourcoing (R1) – Reims (L2)</strong>, samedi à 14h.</li><li><strong>Boulay (R1) – Sochaux (L2)</strong>, samedi à 14h30.</li><li><strong>Firminy (R1) – Annecy (L2)</strong>, samedi à 17h.</li><li><strong>Béthune (R1) – Nancy (L2)</strong>, samedi à 18h.</li><li><strong>Lourdes (R1) – Pau (L2)</strong>, samedi à 19h.</li><li><strong>Châteaubourg (R1) – Nantes (L2)</strong>, dimanche à 14h, à Vitré.</li><li><strong>Saint-Renan (R1) – Laval (L2)</strong> et <strong>Saint-Dié (R1) – Metz (L2)</strong>, dimanche à 14h.</li></ul><h2>Les Ligue 3 aussi en danger</h2><p>La nouvelle Ligue 3 n''est pas à l''abri. Deux affiches font particulièrement rêver :</p><ul><li><strong>Choisy-au-Bac (R2) – Caen (L3)</strong>, samedi à 16h. Quatre divisions d''écart.</li><li><strong>Cambrai Amérique (R3) – Amiens (L3)</strong>, samedi à 20h. Cinq divisions d''écart !</li></ul><p>À surveiller aussi : Tinténiac-Saint-Domineuc (R1) contre Concarneau, Saint-Brieuc (R1) contre Rouen, ou encore Pont-de-Chéruy (R2) contre Bourg-en-Bresse.</p><h2>Les petits poucets</h2><p>Le plus petit qualifié de métropole s''appelle <strong>Violaines</strong>. Ce club de D2 de district (Pas-de-Calais) reçoit Vermelles (R3) dimanche à 14h, avec une place au 8e tour à la clé.</p><p>Certains ont déjà fait tomber des gros au tour précédent. Au 6e tour, <strong>Val Yerres Crosne</strong> (R2) a sorti la JA Drancy (N2) au bout d''un match fou (4-3). En Deux-Sèvres, <strong>Bressuire</strong> (R1) a déjà éliminé Chauray (N1) et Panazol (N2) chez lui. Il reçoit Challans (N2) samedi.</p><h2>Les affiches à part</h2><ul><li><strong>Versailles (L3) – Rodez (L2)</strong> : le capitaine ruthénois Raphaël Lipinski va affronter son petit frère Éthane, 18 ans, qui joue à Versailles.</li><li><strong>Paris 13 Atletico (L3) – Red Star (L2)</strong> : un derby parisien, dimanche à 14h.</li><li><strong>Rumilly-Vallières (N1) – Saint-Étienne (L2)</strong>, dimanche à 15h à Annecy, pour clore le week-end.</li><li>Les clubs d''outre-mer sont aussi là : Le Puy (L3) reçoit les Diables Noirs de Combani (Mayotte), et Châteaubriant (N1) affronte Horizon Patho (Nouvelle-Calédonie).</li></ul><p>La Coupe de France, c''est ça : un terrain, 90 minutes, et tout devient possible. Passe D vous racontera les exploits du week-end. 🏆</p><h2>Sources</h2><p><a href="https://www.ouest-france.fr/sport/football/coupe-de-france/coupe-de-france-dates-horaires-le-programme-des-matches-du-7e-tour-pour-les-clubs-de-louest-et-de-ligue-2-9767d5ee-d9ec-11f1-81f5-8e32b0872d76" target="_blank" rel="noopener noreferrer">Ouest-France</a>, <a href="https://footamateur.ouest-france.fr/coupe-de-france-le-programme-des-ligue-3-pour-le-septieme-tour/" target="_blank" rel="noopener noreferrer">Foot Amateur</a>, <a href="https://www.foot-national.com/coupe-de-france/horaires-dates-la-programmation-complete-du-septieme-tour-de-la-coupe-de-france-961858" target="_blank" rel="noopener noreferrer">Foot National</a>, <a href="https://www.lanouvellerepublique.fr/niort/coupe-de-france-nueillaubiers-jouera-a-cholet-les-chamois-niortais-saint-flo-un-dimanche-1793701264" target="_blank" rel="noopener noreferrer">La Nouvelle République</a>, <a href="https://paris-idf.fff.fr/simple/" target="_blank" rel="noopener noreferrer">Ligue Paris Île-de-France</a>.</p><p>— Passe D</p>', 'article', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'football-amateur'),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  now(), now(), 3, false, 'Coupe de France: Ligue 2 clubs join in, the underdogs dream', 'From 12 to 15 November, the Coupe de France 7th round sees Ligue 2 clubs enter. Chambéry-Grenoble, Cambrai-Amiens, Choisy-au-Bac-Caen, little Violaines… Passe D picks the ties not to miss.', '<p>This is the moment every small club waits for. From Thursday 12 to Sunday 15 November, the 7th round of the Coupe de France marks the entry of <strong>Ligue 2</strong> clubs. Facing them are regional teams, sometimes district sides, playing the game of their lives. Passe D picks out the ties not to miss.</p><h2>David against Goliath</h2><ul><li><strong>Chambéry (R1) – Grenoble (L2)</strong>, Thursday 12 November at 7pm. The opening game, against Ligue 2''s bottom club. The trap is set.</li><li><strong>Tourcoing (R1) – Reims (L2)</strong>, Saturday at 2pm.</li><li><strong>Boulay (R1) – Sochaux (L2)</strong>, Saturday at 2.30pm.</li><li><strong>Firminy (R1) – Annecy (L2)</strong>, Saturday at 5pm.</li><li><strong>Béthune (R1) – Nancy (L2)</strong>, Saturday at 6pm.</li><li><strong>Lourdes (R1) – Pau (L2)</strong>, Saturday at 7pm.</li><li><strong>Châteaubourg (R1) – Nantes (L2)</strong>, Sunday at 2pm, in Vitré.</li><li><strong>Saint-Renan (R1) – Laval (L2)</strong> and <strong>Saint-Dié (R1) – Metz (L2)</strong>, Sunday at 2pm.</li></ul><p><em>R1, R2, R3 are regional leagues (6th to 8th tiers); district leagues are below.</em></p><h2>Ligue 3 clubs in danger too</h2><p>The new Ligue 3 is not safe either. Two ties stand out:</p><ul><li><strong>Choisy-au-Bac (R2) – Caen (L3)</strong>, Saturday at 4pm. Four divisions apart.</li><li><strong>Cambrai Amérique (R3) – Amiens (L3)</strong>, Saturday at 8pm. Five divisions apart!</li></ul><p>Also worth watching: Tinténiac-Saint-Domineuc (R1) against Concarneau, Saint-Brieuc (R1) against Rouen, and Pont-de-Chéruy (R2) against Bourg-en-Bresse.</p><h2>The underdogs</h2><p>The smallest club left in mainland France is <strong>Violaines</strong>. This district D2 side (Pas-de-Calais) hosts Vermelles (R3) on Sunday at 2pm, with a place in the 8th round at stake.</p><p>Some have already toppled bigger teams. In the 6th round, <strong>Val Yerres Crosne</strong> (R2) knocked out JA Drancy (N2) after a crazy game (4-3). In the Deux-Sèvres, <strong>Bressuire</strong> (R1) has already beaten Chauray (N1) and Panazol (N2) at home. They host Challans (N2) on Saturday.</p><h2>Special ties</h2><ul><li><strong>Versailles (L3) – Rodez (L2)</strong>: Rodez captain Raphaël Lipinski will face his little brother Éthane, 18, who plays for Versailles.</li><li><strong>Paris 13 Atletico (L3) – Red Star (L2)</strong>: a Paris derby, Sunday at 2pm.</li><li><strong>Rumilly-Vallières (N1) – Saint-Étienne (L2)</strong>, Sunday at 3pm in Annecy, to close the weekend.</li><li>Overseas clubs are there too: Le Puy (L3) host Diables Noirs de Combani (Mayotte), and Châteaubriant (N1) face Horizon Patho (New Caledonia).</li></ul><p>That is the Coupe de France: one pitch, 90 minutes, and anything can happen. Passe D will bring you the weekend''s giant-killings. 🏆</p><h2>Sources</h2><p><a href="https://www.ouest-france.fr/sport/football/coupe-de-france/coupe-de-france-dates-horaires-le-programme-des-matches-du-7e-tour-pour-les-clubs-de-louest-et-de-ligue-2-9767d5ee-d9ec-11f1-81f5-8e32b0872d76" target="_blank" rel="noopener noreferrer">Ouest-France</a>, <a href="https://footamateur.ouest-france.fr/coupe-de-france-le-programme-des-ligue-3-pour-le-septieme-tour/" target="_blank" rel="noopener noreferrer">Foot Amateur</a>, <a href="https://www.foot-national.com/coupe-de-france/horaires-dates-la-programmation-complete-du-septieme-tour-de-la-coupe-de-france-961858" target="_blank" rel="noopener noreferrer">Foot National</a>, <a href="https://www.lanouvellerepublique.fr/niort/coupe-de-france-nueillaubiers-jouera-a-cholet-les-chamois-niortais-saint-flo-un-dimanche-1793701264" target="_blank" rel="noopener noreferrer">La Nouvelle République</a>, <a href="https://paris-idf.fff.fr/simple/" target="_blank" rel="noopener noreferrer">Ligue Paris Île-de-France</a>.</p><p>— Passe D</p>', true
ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured", "en_title", "en_dek", "en_body_html", "en_published")
SELECT 'Coupe Gambardella : les surprises du 5e tour', 'coupe-gambardella-les-surprises-du-5e-tour', 'Muzolais, petit club de district, s''offre une qualification historique. Rhône Crussol et Clermont Saint-Jacques font tomber des équipes du niveau supérieur. L''ASPTT Marseille renverse tout au bout du temps additionnel. Passe D vous raconte les exploits du week-end.', '<p>La Coupe Gambardella, c''est la Coupe de France des moins de 19 ans. Et comme chez les grands, les petits clubs adorent y jouer les trouble-fêtes. Le week-end des 7 et 8 novembre, le 5e tour a offert son lot de surprises. Passe D vous présente ceux qui ont fait mentir la hiérarchie.</p><h2>Muzolais, la qualification historique</h2><p>C''est la plus belle histoire du week-end. Le <strong>FC Muzolais</strong>, petit club ardéchois qui joue au niveau district, recevait Limonest. Mené dès le début du match, il a renversé la situation dans les dernières minutes pour s''imposer 2-1. Une qualification historique pour le 6e tour, selon la Ligue Auvergne-Rhône-Alpes.</p><p>Sur les sept équipes de district encore en course dans la région, seules deux passent. L''autre, c''est l''<strong>ABH Football</strong>, qui a remporté le derby de la Loire contre Firminy (2-1).</p><h2>Les R2 qui font tomber les R1</h2><p>Dans la même région, deux équipes de U18 R2 ont battu des adversaires du niveau supérieur (U18 R1) :</p><ul><li><strong>Rhône Crussol Foot 07</strong> (Saint-Péray, en Ardèche) signe, selon Le Dauphiné, une qualification historique pour le 6e tour.</li><li><strong>L''AS Clermont Saint-Jacques</strong> poursuit lui aussi l''aventure.</li></ul><p>Le FC Seyssins (R2) s''est aussi qualifié en battant Oyonnax 2-1, et le GOAL FC a pris le meilleur sur Côte Foot (2-0).</p><h2>ASPTT Marseille, le renversement</h2><p>En Provence, l''<strong>ASPTT Marseille</strong> a vécu une fin de match folle contre l''AS Cagnes-Le Cros. Menés, les Marseillais ont renversé la rencontre dans le temps additionnel (3-2), portés par un public bruyant et par <strong>Loris Muzyczyn</strong>, auteur d''un triplé. Ils filent vers le tour fédéral.</p><h2>Les favoris ont tenu leur rang</h2><p>Tous les gros n''ont pas tremblé. Grenoble s''est imposé 5-0 à Thonon Évian, Bourgoin a battu Millery-Vourles 8-0, le FC Lyon a éliminé Rive-de-Gier 6-0, Villefranche a gagné 5-1 à Roche-Saint-Genest et Chambéry 5-1 à Colombier-Satolas.</p><h2>Et maintenant ?</h2><p>Le 6e tour, la finale régionale, se joue le week-end des 21 et 22 novembre. Les tirages ont lieu cette semaine dans les ligues : en Grand Est, par exemple, Ludres recevra Épinal et Jarville accueillera Sedan.</p><p>Ensuite, place au 7e tour, le premier tour fédéral, le 13 décembre. C''est là qu''entrent en jeu les centres de formation des clubs pros, comme l''OL. Pour Muzolais et les autres, le rêve de défier un grand est à deux matchs. 🌟</p><h2>Sources</h2><p><a href="https://laurafoot.fff.fr/simple/" target="_blank" rel="noopener noreferrer">Ligue Auvergne-Rhône-Alpes (FFF)</a>, <a href="https://www.leprogres.fr/sport/2026/11/09/coupe-gambardella-plus-que-trois-clubs-rhodaniens-en-lice-pour-le-6e-tour-en-attendant-l-ol" target="_blank" rel="noopener noreferrer">Le Progrès</a>, <a href="https://www.ledauphine.com/sport/2026/11/09/rhone-crussol-foot-07-les-u18-creent-l-exploit-en-gambardella" target="_blank" rel="noopener noreferrer">Le Dauphiné</a>, <a href="https://www.laprovence.com/article/sports/25439272742995/football-coupe-gambardella-au-bout-du-suspense-l-asptt-marseille-s-impose-contre-l-as-cagnes-le-cros" target="_blank" rel="noopener noreferrer">La Provence</a>, <a href="https://www.estrepublicain.fr/sport/2026/11/09/saint-max-essey-ludres-jarville-et-pagny-connaissent-leur-adversaire-en-finale-regionale-de-gambardella" target="_blank" rel="noopener noreferrer">L''Est Républicain</a>.</p><p>— Passe D</p>', 'article', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'football-amateur'),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  now(), now(), 3, false, 'Coupe Gambardella: the surprises of the 5th round', 'Muzolais, a small district club, make history. Rhône Crussol and Clermont Saint-Jacques knock out higher-level teams. ASPTT Marseille turn it around in stoppage time. Passe D brings you the weekend''s upsets.', '<p>The Coupe Gambardella is France''s national cup for under-19s. And just like the senior version, small clubs love to cause upsets. On the weekend of 7 and 8 November, the 5th round delivered its share of surprises. Passe D introduces the teams who defied the odds.</p><h2>Muzolais make history</h2><p>It is the best story of the weekend. <strong>FC Muzolais</strong>, a small club from the Ardèche playing at district level, hosted Limonest. Behind from the start, they turned the game around in the final minutes to win 2-1. A historic qualification for the 6th round, according to the Auvergne-Rhône-Alpes league.</p><p>Of the seven district teams still in the running in the region, only two went through. The other is <strong>ABH Football</strong>, who won the Loire derby against Firminy (2-1).</p><h2>R2 sides topple R1 teams</h2><p>In the same region, two U18 R2 teams beat opponents from the level above (U18 R1):</p><ul><li><strong>Rhône Crussol Foot 07</strong> (Saint-Péray, Ardèche) reached the 6th round for the first time, according to Le Dauphiné.</li><li><strong>AS Clermont Saint-Jacques</strong> are also still in the competition.</li></ul><p>FC Seyssins (R2) also went through by beating Oyonnax 2-1, and GOAL FC got the better of Côte Foot (2-0).</p><h2>ASPTT Marseille turn it around</h2><p>In Provence, <strong>ASPTT Marseille</strong> had a crazy finish against AS Cagnes-Le Cros. Trailing, they turned the game around in stoppage time (3-2), carried by a loud crowd and by <strong>Loris Muzyczyn</strong>, who scored a hat-trick. They are heading for the federal round.</p><h2>The favourites held firm</h2><p>Not all the big teams wobbled. Grenoble won 5-0 at Thonon Évian, Bourgoin beat Millery-Vourles 8-0, FC Lyon knocked out Rive-de-Gier 6-0, Villefranche won 5-1 at Roche-Saint-Genest and Chambéry 5-1 at Colombier-Satolas.</p><h2>What next?</h2><p>The 6th round, the regional final, will be played on the weekend of 21 and 22 November. The draws are taking place this week in each league: in the Grand Est, for example, Ludres will host Épinal and Jarville will welcome Sedan.</p><p>Then comes the 7th round, the first federal round, on 13 December. That is when the academies of professional clubs, such as Lyon, join the competition. For Muzolais and the others, the dream of facing a big club is two games away. 🌟</p><h2>Sources</h2><p><a href="https://laurafoot.fff.fr/simple/" target="_blank" rel="noopener noreferrer">Ligue Auvergne-Rhône-Alpes (FFF)</a>, <a href="https://www.leprogres.fr/sport/2026/11/09/coupe-gambardella-plus-que-trois-clubs-rhodaniens-en-lice-pour-le-6e-tour-en-attendant-l-ol" target="_blank" rel="noopener noreferrer">Le Progrès</a>, <a href="https://www.ledauphine.com/sport/2026/11/09/rhone-crussol-foot-07-les-u18-creent-l-exploit-en-gambardella" target="_blank" rel="noopener noreferrer">Le Dauphiné</a>, <a href="https://www.laprovence.com/article/sports/25439272742995/football-coupe-gambardella-au-bout-du-suspense-l-asptt-marseille-s-impose-contre-l-as-cagnes-le-cros" target="_blank" rel="noopener noreferrer">La Provence</a>, <a href="https://www.estrepublicain.fr/sport/2026/11/09/saint-max-essey-ludres-jarville-et-pagny-connaissent-leur-adversaire-en-finale-regionale-de-gambardella" target="_blank" rel="noopener noreferrer">L''Est Républicain</a>.</p><p>— Passe D</p>', true
